import { test } from 'node:test';
import assert from 'node:assert/strict';
import { observabilidadeELogging, classificarStatus } from './solution.mjs';

test('formata uma linha de log estruturado com timestamp', () => {
  const linha = observabilidadeELogging({ level: 'info', msg: 'servidor subiu' });
  const objeto = JSON.parse(linha);
  assert.equal(objeto.level, 'info');
  assert.equal(objeto.msg, 'servidor subiu');
  assert.ok(typeof objeto.timestamp === 'string' && !Number.isNaN(Date.parse(objeto.timestamp)));
});

test('mantém os campos originais no log', () => {
  const objeto = JSON.parse(observabilidadeELogging({ status: 500, duracaoMs: 12 }));
  assert.equal(objeto.status, 500);
  assert.equal(objeto.duracaoMs, 12);
});

test('classifica status 4xx como warn', () => {
  assert.equal(classificarStatus(404), 'warn');
  assert.equal(classificarStatus(429), 'warn');
});

test('classifica status 5xx como error e outros como info', () => {
  assert.equal(classificarStatus(500), 'error');
  assert.equal(classificarStatus(200), 'info');
});

solutionCode:
export function observabilidadeELogging(log) {
  return JSON.stringify({ ...log, timestamp: new Date().toISOString() });
}

export function classificarStatus(status) {
  if (status >= 400 && status < 500) return 'warn';
  if (status >= 500 && status < 600) return 'error';
  return 'info';
}
